"""Freeze new, author-labelled answers before any inference or prompt change."""
from pathlib import Path
from datetime import datetime, timezone
import hashlib
import json
import re
import shutil
import subprocess

root = Path(__file__).resolve().parents[1]
source = root / 'lat-ai'
out = root / 'outputs/assessment-unseen-2026-11-11'
out.mkdir()  # Do not overwrite an earlier experiment.
cases = []
def add(task, kind, answer, expected, rationale):
    cases.append(dict(id=f'U{len(cases)+1:02d}', task_key=task, category=kind,
                      answer=answer, expected=[bool(x) for x in expected], rationale=rationale))

t = 'L1.types.1'
add(t,'correct','В кавычках лежат два текста: 3 и 2. Плюс приписывает второй текст к первому, арифметической суммы тут нет. Увидим 32.',[1,1,1],'Тип обоих операндов, конкатенация и точный вывод указаны.')
add(t,'correct','Результат на экране — 32. Он получается склейкой: оператор + соединяет строку «3» со строкой «2», а не складывает числа.',[1,1,1],'Обратный порядок объяснения не влияет на три критерия.')
